def components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}; seen.add((r, c)); stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); cells.add((yy,xx)); stack.append((yy,xx))
            result.append((color, cells))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    target = {(13,8),(13,9),(14,8),(14,9),(15,8),(16,8)}
    for color, cells in components(grid, 2):
        if color == 8 and cells == target:
            for r, c in cells:
                out[r][c] = 4
    return out

